import collections

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self._cache = collections.OrderedDict()
        self.hits = 0
        self.misses = 0
        self.evictions = 0
        self.expirations = 0

    def _remove_expired(self):
        current_time = self.clock()
        expired_keys = [
            key for key, (value, expiry) in self._cache.items()
            if expiry <= current_time
        ]
        for key in expired_keys:
            del self._cache[key]
            self.expirations += 1

    def _evict(self):
        if self._cache:
            self._cache.popitem(last=False)
            self.evictions += 1

    def put(self, key, value):
        if self.capacity <= 0:
            return
        self._remove_expired()
        if key in self._cache:
            self._cache.move_to_end(key, last=True)
        else:
            while len(self._cache) >= self.capacity:
                self._evict()
        current_time = self.clock()
        expiry = current_time + self.ttl
        self._cache[key] = (value, expiry)

    def get(self, key, default=None):
        if self.capacity <= 0:
            self.misses += 1
            return default
        current_time = self.clock()
        if key not in self._cache:
            self.misses += 1
            return default
        value, expiry = self._cache[key]
        if current_time >= expiry:
            del self._cache[key]
            self.expirations += 1
            self.misses += 1
            return default
        else:
            self._cache.move_to_end(key, last=True)
            self.hits += 1
            return value

    def __len__(self):
        current_time = self.clock()
        return sum(1 for _, expiry in self._cache.values() if expiry > current_time)

    def stats(self):
        return {
            'hits': self.hits,
            'misses': self.misses,
            'evictions': self.evictions,
            'expirations': self.expirations
        }
