import unicodedata
import re

def slugify(title: str, max_len: int = 50) -> str:
    slug = unicodedata.normalize('NFKD', title).encode('ascii', 'ignore').decode('ascii').lower()
    slug = re.sub(r'[^a-z0-9]+', '-', slug).strip('-')
    if len(slug) <= max_len:
        return slug
    parts = slug.split('-')
    new_parts = []
    current_len = 0
    for part in parts:
        if not new_parts:
            if len(part) > max_len:
                return part[:max_len]
            new_parts.append(part)
            current_len = len(part)
        else:
            add_len = current_len + 1 + len(part)
            if add_len > max_len:
                break
            new_parts.append(part)
            current_len = add_len
    return '-'.join(new_parts)
